{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "The studies were eligible for inclusion if they met the following criteria: (1) Patients who suffered and were treated for an extra-articular distal radius fracture; (2) age 18 years or older; (3) patients were either treated using a plaster cast, K-wire(s), plate fixation, external fixator, or an intramedullary device; (4) primary data for at least one outcome parameter had to be available.",
      "reason": "Eligibility criteria specify population/fracture type, age setting, eligible interventions, and data requirement."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "No language limits were used and any potentially eligible non-English language manuscripts were translated if possible by native speaking colleagues or using Google translate, if no native speaker was available.",
      "reason": "Language handling is specified, but no dissemination year range or publication status criteria are reported."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_6",
      "quote": "Studies without a clear description of fracture type or intervention, or studies that lacked sufficient data for analysis were excluded.",
      "reason": "Exclusion for lacking sufficient data is mentioned, but the review does not distinguish absence of outcome measurement from non-reporting of measured outcomes."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Among the 136 cohorts, 31 reported on outcomes after plaster cast immobilization [18-48], 37 on K-wire fixation [5, 18, 21, 41, 42, 45, 47, 49-76], 41 on volar plate fixation [4-6, 54-56, 60, 61, 72, 74, 77-107], 16 on external fixation",
      "reason": "Synthesis groups are defined as the five treatment modalities (also listed in inclusion criterion 3), matching the review objective of comparing treatments for extra-articular distal radius fractures; follow-up periods for pooling are also specified."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": "text_6",
      "quote": "Studies describing a not-commonly used device or technique for extra-articular fractures were excluded ( i.e. dorsal plates, Epibloc system, cannulated screw, above elbow cast, etc.).",
      "reason": "Notable restrictions (e.g., excluding less common devices) are stated without a rationale for those restrictions."
    }
  ],
  "confidence": 85
}

